* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1c2c;
  color: #f4f4f4;
  font-family: 'Courier New', Courier, monospace;
}

.quiz {
  background: #30346d;
  border: 4px solid #f4f4f4;
  box-shadow: 0 0 0 4px #000, 8px 8px 0 0 #000;
  padding: 2rem;
  text-align: center;
  width: min(90vw, 400px);
}

.question {
  margin: 0 0 1rem;
  font-size: 2.2rem;
  image-rendering: pixelated;
  text-shadow: 2px 2px 0 #000;
}

.score-row {
  margin: 0 0 1.5rem;
  font-size: 1.3rem;
}

.answers, .controls {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font: inherit;
  font-size: 1.5rem;
  background: #f4f4f4;
  color: #1a1c2c;
  border: 4px solid #000;
  box-shadow: 4px 4px 0 0 #000;
  padding: 0.5rem 1.1rem;
  cursor: pointer;
  image-rendering: pixelated;
}

button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
  box-shadow: none;
  transform: translate(4px, 4px);
}

button:not(:disabled):hover {
  background: #ffcd75;
}

button:focus-visible {
  outline: 3px dashed #fff;
  outline-offset: 4px;
}

const questions = [
  { text: '2 + 2 = ?', answers: ['4', '5'], correct: 'a' },
  { text: '3 + 3 = ?', answers: ['5', '6'], correct: 'b' }
];

let current = 0;
let score = 0;
let answered = false;

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');
const scoreEl = document.getElementById('score');

function setQuestion(index) {
  const q = questions[index];
  questionEl.textContent = q.text;
  answerA.textContent = q.answers[0];
  answerB.textContent = q.answers[1];
  answerA.disabled = false;
  answerB.disabled = false;
  answered = false;
  nextBtn.disabled = true;
}

function answer(choice) {
  if (answered) return;
  answered = true;
  answerA.disabled = true;
  answerB.disabled = true;
  if (choice === questions[current].correct) {
    score += 1;
    scoreEl.textContent = score;
  }
  nextBtn.disabled = false;
}

function finish() {
  questionEl.textContent = 'Finished';
  answerA.disabled = true;
  answerB.disabled = true;
  nextBtn.disabled = true;
}

function next() {
  if (!answered) return;
  if (current === 0) {
    current = 1;
    setQuestion(current);
  } else if (current === 1) {
    finish();
    current = 2;
  }
}

function restart() {
  current = 0;
  score = 0;
  scoreEl.textContent = score;
  setQuestion(current);
}

answerA.addEventListener('click', () => answer('a'));
answerB.addEventListener('click', () => answer('b'));
nextBtn.addEventListener('click', next);
restartBtn.addEventListener('click', restart);

setQuestion(0);
